            seen_warmup=True
        elif arg in ("-m","--min-runs"):
            if seen_min: error_clap("the argument '--min-runs <NUM>' cannot be used multiple times")
            v=require("--min-runs",i+1); i+=1; min_runs=v; seen_min=True
        elif arg.startswith("--min-runs="):
            if seen_min: error_clap("the argument '--min-runs <NUM>' cannot be used multiple times")
            min_runs=arg.split("=",1)[1]; seen_min=True
        elif arg in ("-M","--max-runs"):
            if seen_max: error_clap("the argument '--max-runs <NUM>' cannot be used multiple times")
            v=require("--max-runs",i+1); i+=1; max_runs=v; seen_max=True
        elif arg.startswith("--max-runs="):
            if seen_max: error_clap("the argument '--max-runs <NUM>' cannot be used multiple times")
            max_runs=arg.split("=",1)[1]; seen_max=True
        elif arg in ("-r","--runs"):
            if seen_runs: error_clap("the argument '--runs <NUM>' cannot be used multiple times")
            v=require("--runs",i+1); i+=1; runs=v; seen_runs=True
        elif arg.startswith("--runs="):
            if seen_runs: error_clap("the argument '--runs <NUM>' cannot be used multiple times")
            runs=arg.split("=",1)[1]; seen_runs=True
        elif arg in ("-s","--setup"):
            v=require("--setup",i+1); i+=1; setup_cmds.append(v)
        elif arg.startswith("--setup="):
            setup_cmds.append(arg.split("=",1)[1])
        elif arg=="--reference":
            if seen_ref: error_clap("the argument '--reference <CMD>' cannot be used multiple times")
            v=require("--reference",i+1); i+=1; reference=v; seen_ref=True
        elif arg.startswith("--reference="):
            if seen_ref: error_clap("the argument '--reference <CMD>' cannot be used multiple times")
            reference=arg.split("=",1)[1]; seen_ref=True
        elif arg=="--reference-name":
            if seen_ref_name: error_clap("the argument '--reference-name <CMD>' cannot be used multiple times")
            v=require("--reference-name",i+1); i+=1; reference_name=v; seen_ref_name=True
        elif arg.startswith("--reference-name="):
            if seen_ref_name: error_clap("the argument '--reference-name <CMD>' cannot be used multiple times")
            reference_name=arg.split("=",1)[1]; seen_ref_name=True
        elif arg in ("-p","--prepare"):
            v=require("--prepare",i+1); i+=1; prepare_cmds.append(v)
        elif arg.startswith("--prepare="):
            prepare_cmds.append(arg.split("=",1)[1])
        elif arg.startswith("-p") and arg!="-p":
            prepare_cmds.append(arg[2:])
        elif arg in ("-C","--conclude"):
            v=require("--conclude",i+1); i+=1; conclude_cmds.append(v)
        elif arg.startswith("--conclude="):
            conclude_cmds.append(arg.split("=",1)[1])
        elif arg in ("-c","--cleanup"):
            v=require("--cleanup",i+1); i+=1; cleanup_cmds.append(v)
        elif arg.startswith("--cleanup="):
            cleanup_cmds.append(arg.split("=",1)[1])
        elif arg in ("-P","--parameter-scan"):
            if i+3>=n: error_clap("a value is required for '--parameter-scan <VAR> <MIN> <MAX>' but none was supplied")
            var=argv[i+1]; mn=argv[i+2]; mx=argv[i+3]; param_scans.append((var,mn,mx)); i+=3
        elif arg.startswith("--parameter-scan="):
            error_clap("a value is required for '--parameter-scan <VAR> <MIN> <MAX>' but none was supplied")
        elif arg in ("-D","--parameter-step-size"):
            if seen_step: error_clap("the argument '--parameter-step-size <DELTA>' cannot be used multiple times")
            v=require("--parameter-step-size",i+1); i+=1; param_step=v; seen_step=True
        elif arg.startswith("--parameter-step-size="):
            if seen_step: error_clap("the argument '--parameter-step-size <DELTA>' cannot be used multiple times")
            param_step=arg.split("=",1)[1]; seen_step=True
        elif arg.startswith("-D") and arg!="-D":
            if seen_step: error_clap("the argument '--parameter-step-size <DELTA>' cannot be used multiple times")
            param_step=arg[2:]; seen_step=True
        elif arg in ("-L","--parameter-list"):
            if i+2>=n: error_clap("a value is required for '--parameter-list <VAR> <VALUES>' but none was supplied")
            var=argv[i+1]; vals=argv[i+2]; param_lists.append((var,vals)); i+=2
        elif arg.startswith("--parameter-list="):
            error_clap("a value is required for '--parameter-list <VAR> <VALUES>' but none was supplied")
        elif arg in ("-S","--shell"):
            if seen_shell: error_clap("the argument '--shell <SHELL>' cannot be used multiple times")
            v=require("--shell",i+1); i+=1; shell_opt=v; seen_shell=True
        elif arg.startswith("--shell="):
            if seen_shell: error_clap("the argument '--shell <SHELL>' cannot be used multiple times")
            shell_opt=arg.split("=",1)[1]; seen_shell=True
        elif arg=="-N":
            shell_opt="none"; seen_shell=True
        elif arg in ("-i","--ignore-failure"):
            nxt=argv[i+1] if i+1<n else None
            if nxt is not None and not nxt.startswith("-") and (nxt=="all-non-zero" or re.match(r'^[0-9,]+$', nxt)):
                ignore_failure=nxt; i+=1
            else:
                ignore_failure=""
            # store later
        elif arg.startswith("--ignore-failure="):
            ignore_failure=arg.split("=",1)[1]
        elif arg.startswith("-i") and arg!="-i":
            ignore_failure=arg[2:]
        elif arg=="--style":
            if seen_style: error_clap("the argument '--style <TYPE>' cannot be used multiple times")
            v=require("--style",i+1); i+=1; style=v; seen_style=True
        elif arg.startswith("--style="):
            if seen_style: error_clap("the argument '--style <TYPE>' cannot be used multiple times")
            style=arg.split("=",1)[1]; seen_style=True
        elif arg=="--sort":
            if seen_sort: error_clap("the argument '--sort <METHOD>' cannot be used multiple times")
            v=require("--sort",i+1); i+=1; sort=v; seen_sort=True
        elif arg.startswith("--sort="):
            if seen_sort: error_clap("the argument '--sort <METHOD>' cannot be used multiple times")
            sort=arg.split("=",1)[1]; seen_sort=True
        elif arg in ("-u","--time-unit"):
            if seen_time_unit: error_clap("the argument '--time-unit <UNIT>' cannot be used multiple times")
            v=require("--time-unit",i+1); i+=1; time_unit=v; seen_time_unit=True
        elif arg.startswith("--time-unit="):
            if seen_time_unit: error_clap("the argument '--time-unit <UNIT>' cannot be used multiple times")
            time_unit=arg.split("=",1)[1]; seen_time_unit=True
        elif arg.startswith("-u") and arg!="-u":
            if seen_time_unit: error_clap("the argument '--time-unit <UNIT>' cannot be used multiple times")
            time_unit=arg[2:]; seen_time_unit=True
        elif arg=="--export-asciidoc":
            v=require("--export-asciidoc",i+1); i+=1; export_asciidoc=v
        elif arg.startswith("--export-asciidoc="):
            export_asciidoc=arg.split("=",1)[1]
        elif arg=="--export-csv":
            v=require("--export-csv",i+1); i+=1; export_csv=v
        elif arg.startswith("--export-csv="):
            export_csv=arg.split("=",1)[1]
        elif arg=="--export-json":
            v=require("--export-json",i+1); i+=1; export_json=v
        elif arg.startswith("--export-json="):
            export_json=arg.split("=",1)[1]
        elif arg=="--export-markdown":
            v=require("--export-markdown",i+1); i+=1; export_markdown=v
        elif arg.startswith("--export-markdown="):
            export_markdown=arg.split("=",1)[1]
        elif arg=="--export-orgmode":
            v=require("--export-orgmode",i+1); i+=1; export_orgmode=v
        elif arg.startswith("--export-orgmode="):
            export_orgmode=arg.split("=",1)[1]
        elif arg=="--show-output":
            show_output=True
        elif arg=="--output":
            v=require("--output",i+1); i+=1; output_where.append(v)
        elif arg.startswith("--output="):
            output_where.append(arg.split("=",1)[1])
        elif arg=="--input":
            if seen_input: error_clap("the argument '--input <WHERE>' cannot be used multiple times")
            v=require("--input",i+1); i+=1; input_where=v; seen_input=True
        elif arg.startswith("--input="):
            if seen_input: error_clap("the argument '--input <WHERE>' cannot be used multiple times")
            input_where=arg.split("=",1)[1]; seen_input=True
        elif arg in ("-n","--command-name"):
            v=require("--command-name",i+1); i+=1; command_names.append(v)
        elif arg.startswith("--command-name="):
            command_names.append(arg.split("=",1)[1])
        elif arg.startswith("-n") and arg!="-n":
            command_names.append(arg[2:])
        elif arg.startswith("-"):
            error_clap(f"unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'")
        else:
            commands.append(arg)
        i+=1
    # validation
    if param_step is not None and not param_scans:
        error_clap("the following required arguments were not provided:\n  --parameter-scan <VAR> <MIN> <MAX>", usage="executable --parameter-scan <VAR> <MIN> <MAX> --parameter-step-size <DELTA> <command>...")
    if reference_name is not None and reference is None:
        error_clap("the following required arguments were not provided:\n  --reference <CMD>", usage="executable --reference <CMD> --reference-name <CMD> <command>...")
    if show_output and seen_style:
        error_clap("the argument '--style <TYPE>' cannot be used with '--show-output'", usage="executable --runs <NUM> --warmup <NUM> --prepare <CMD> --setup <CMD> --cleanup <CMD> --conclude <CMD> --style <TYPE> <command>...")
    if runs is not None and min_runs is not None:
        error_clap("the argument '--runs <NUM>' cannot be used with '--min-runs <NUM>'", usage="executable --runs <NUM> <command>...")
    if runs is not None and max_runs is not None:
        error_clap("the argument '--runs <NUM>' cannot be used with '--max-runs <NUM>'", usage="executable --runs <NUM> <command>...")
    if style not in ("auto","basic","full","nocolor","color","none"):
        error_clap(f"invalid value '{style}' for '--style <TYPE>'\n  [possible values: auto, basic, full, nocolor, color, none]")
    if sort not in ("auto","command","mean-time"):
        error_clap(f"invalid value '{sort}' for '--sort <METHOD>'\n  [possible values: auto, command, mean-time]")
    if time_unit is not None and time_unit not in ("microsecond","millisecond","second"):
        error_clap(f"invalid value '{time_unit}' for '--time-unit <UNIT>'\n  [possible values: microsecond, millisecond, second]")
    # numeric parsing
    warmup_val=0
    if warmup is not None:
        warmup_val=parse_int_arg("--warmup", warmup)
    min_runs_val=10
    if min_runs is not None:
        min_runs_val=parse_int_arg("--min-runs", min_runs)
    max_runs_val=None
    if max_runs is not None:
        max_runs_val=parse_int_arg("--max-runs", max_runs)
    runs_val=None
    if runs is not None:
        runs_val=parse_int_arg("--runs", runs)
    # ignore failure parse
    ignore_all=False; ignore_set=set()
    if 'ignore_failure' in locals() and ignore_failure is not None:
        if ignore_failure=="" or ignore_failure=="all-non-zero":
            ignore_all=True
        else:
            try:
                for p in ignore_failure.split(","):
                    p=p.strip()
                    if p=="": continue
                    ignore_set.add(int(p))
            except:
                error_runtime(f"Could not read numeric integer argument to '--ignore-failure': invalid digit found in string")
    else:
        ignore_failure=None

    if not commands:
        error_clap("the following required arguments were not provided:\n  <command>...", usage="executable <command>...")

    shell = shell_opt if shell_opt is not None else "default"
    def shell_exec_for(s):
        if s=="none": return "none"
        if s=="default": return "/bin/sh"
        return s
    shell_exec = shell_exec_for(shell)

    # calibration
    overhead=0.0
    if shell_exec!="none":
        parts=shlex.split(shell_exec)
        calib=[]
        for _ in range(10):
            st=time.perf_counter()
            try:
                proc=subprocess.Popen(parts+["-c",""], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL)
                pid,status,rus=os.wait4(proc.pid,0)
                if not os.WIFEXITED(status) or os.WEXITSTATUS(status)!=0:
                    raise OSError()
                en=time.perf_counter()
                calib.append(en-st)
            except:
                eprint(f"Error: Could not measure shell execution time. Make sure you can run '{shell_exec} -c \"\"'.")
                sys.exit(1)
        calib.sort()
        overhead=statistics.median(calib) if calib else 0

    base_commands=list(commands)
    was_ref=False
    if reference is not None:
        base_commands=[reference]+base_commands
        was_ref=True

    initial=[{"template":cmd,"params":{}, "orig_idx":idx} for idx,cmd in enumerate(base_commands)]
    # param scans
    for (var, min_s, max_s) in param_scans:
        is_float = ('.' in min_s or '.' in max_s or (param_step is not None and '.' in param_step) or 'e' in min_s.lower() or 'e' in max_s.lower())
        values=[]
        if is_float:
            try:
                min_f=float(min_s); max_f=float(max_s)
                step_f=float(param_step) if param_step is not None else 1.0
                if step_f==0: step_f=1.0
                n_steps=int(math.floor((max_f-min_f)/step_f + 1e-9))+1
                for k in range(n_steps):
                    cur=min_f + k*step_f
                    if cur>max_f+1e-9: break
                    s=format(cur, '.10g')
                    values.append(s)
                    if len(values)>10000: break
            except:
                error_runtime("Could not read numeric argument to '--parameter-scan': invalid digit found in string")
        else:
            try:
                min_i=int(min_s); max_i=int(max_s)
                step_i=int(param_step) if param_step is not None else 1
                if step_i==0: step_i=1
                if step_i>0:
                    rng=range(min_i, max_i+1, step_i)
                else:
                    rng=range(min_i, max_i-1, step_i)
                values=[str(v) for v in rng]
            except:
                error_runtime("Could not read numeric argument to '--parameter-scan': invalid digit found in string")
        new=[]
        for ent in initial:
            for v in values:
                np=dict(ent["params"]); np[var]=v
                new.append({"template":ent["template"],"params":np,"orig_idx":ent["orig_idx"]})
        initial=new
    for (var, vals_str) in param_lists:
        vals=[v.strip() for v in vals_str.split(",")]
        new=[]
        for ent in initial:
            for v in vals:
                np=dict(ent["params"]); np[var]=v
                new.append({"template":ent["template"],"params":np,"orig_idx":ent["orig_idx"]})
        initial=new

    benchmarks=[]
    for ent in initial:
        tmpl=ent["template"]; params=ent["params"]
        cmd=tmpl
        for k,v in params.items():
            cmd=cmd.replace("{"+k+"}", v)
        benchmarks.append({"command":cmd,"params":params,"template":tmpl,"orig_idx":ent["orig_idx"]})

    # names
    final_names=[]
    if command_names:
        if len(command_names)==len(benchmarks):
            final_names=list(command_names)
        elif len(command_names)==len(base_commands):
            for b in benchmarks:
                idx=b["orig_idx"]
                if idx < len(command_names):
                    final_names.append(command_names[idx])
                else:
                    final_names.append(b["command"])
        elif len(command_names)==1 and len(benchmarks)>1:
            for i,b in enumerate(benchmarks):
                if i==0: final_names.append(command_names[0])
                else: final_names.append(b["command"])
        else:
            for i,b in enumerate(benchmarks):
                if i < len(command_names):
                    final_names.append(command_names[i])
                else:
                    final_names.append(b["command"])
    else:
        final_names=[b["command"] for b in benchmarks]
    if was_ref and reference_name is not None:
        final_names[0]=reference_name

    def per_list(lst, length):
        if not lst: return [None]*length
        if len(lst)==1: return lst*length
        if len(lst)==length: return lst
        return [lst[i%len(lst)] for i in range(length)]
    prepare_per=per_list(prepare_cmds, len(benchmarks))
    conclude_per=per_list(conclude_cmds, len(benchmarks))
    output_per=per_list(output_where, len(benchmarks))
    setup_per=per_list(setup_cmds, len(benchmarks))
    cleanup_per=per_list(cleanup_cmds, len(benchmarks))

    input_file=None
    if input_where is not None and input_where!="null":
        input_file=input_where
        if not os.path.exists(input_file):
            eprint(f"Error: Could not open input file '{input_file}'")
            sys.exit(1)

    def execute_cmd(cmd_str, shell_ex, overhead_sec, env_extra, stdout_where, show):
        env=os.environ.copy()
        env.update(env_extra)
        stdin_fd=subprocess.DEVNULL
        stdin_obj=None
        if input_file is not None:
            try:
                stdin_obj=open(input_file,'rb')
            except:
                eprint(f"Error: Could not open input file '{input_file}'")
                sys.exit(1)
        # stdout
        is_pipe=False
        close_file=None
        if show:
            stdout_arg=None; stderr_arg=None
        else:
            where=stdout_where
            if where is None or where=="null":
                stdout_arg=subprocess.DEVNULL; stderr_arg=subprocess.DEVNULL
            elif where=="pipe":
                is_pipe=True; stdout_arg=subprocess.PIPE; stderr_arg=subprocess.PIPE
            elif where=="inherit":
                stdout_arg=None; stderr_arg=None
            else:
                try:
                    f=open(where,'wb')
                    stdout_arg=f; stderr_arg=f; close_file=f
                except:
                    eprint(f"Error: Could not open output file '{where}'")
                    sys.exit(1)
        # args
        if shell_ex=="none":
            try:
                args=shlex.split(cmd_str)
                if not args: args=["/bin/sh","-c",""]
            except:
                args=[cmd_str]
        else:
            parts=shlex.split(shell_ex)
            args=parts+["-c", cmd_str]
        start=time.perf_counter()
        try:
            if is_pipe:
                before=resource.getrusage(resource.RUSAGE_CHILDREN)
                st=time.perf_counter()
                proc=subprocess.run(args, stdin=stdin_obj if stdin_obj else subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
                en=time.perf_counter()
                after=resource.getrusage(resource.RUSAGE_CHILDREN)
                wall=en-st
                wall=max(0.0, wall - overhead_sec)
                user=after.ru_utime - before.ru_utime
                syst=after.ru_stime - before.ru_stime
                maxrss=after.ru_maxrss*1024
                ec=proc.returncode
                if stdin_obj: stdin_obj.close()
                if close_file: close_file.close()
                return wall,user,syst,maxrss,ec
            else:
                p_stdin=stdin_obj if stdin_obj else stdin_fd
                # Popen args
                out_arg=stdout_arg
                err_arg=stderr_arg
                # if DEVNULL constant, Popen handles
                proc=subprocess.Popen(args, stdin=p_stdin, stdout=out_arg, stderr=err_arg, env=env)
                pid,status,rus=os.wait4(proc.pid,0)
                en=time.perf_counter()
                wall=en-start
                wall=max(0.0, wall - overhead_sec)
                user=rus.ru_utime; syst=rus.ru_stime; maxrss=rus.ru_maxrss*1024
                if os.WIFEXITED(status):
                    ec=os.WEXITSTATUS(status)
                elif os.WIFSIGNALED(status):
                    ec=128+os.WTERMSIG(status)
                else:
                    ec=1
                if stdin_obj: stdin_obj.close()
                if close_file: close_file.close()
                return wall,user,syst,maxrss,ec
        except FileNotFoundError:
            if stdin_obj: stdin_obj.close()
            if close_file:
                try: close_file.close()
                except: pass
            return 0,0,0,0,127
        except Exception:
            if stdin_obj:
                try: stdin_obj.close()
                except: pass
            if close_file:
                try: close_file.close()
                except: pass
            return 0,0,0,0,127

    results=[]
    is_quiet=(style=="none")
    color_enabled=(style in ("full","color"))

    for b_idx, bench in enumerate(benchmarks):
        cmd=bench["command"]; params=bench["params"]; display=final_names[b_idx]
        # setup
        sc=setup_per[b_idx]
        if sc is not None:
            s_cmd=sc
            for k,v in params.items(): s_cmd=s_cmd.replace("{"+k+"}", v)
            _,_,_,_,ec=execute_cmd(s_cmd, shell_exec, 0, {}, None, show_output)
            if ec!=0:
                if not is_quiet:
                    sys.stdout.write(f"Benchmark {b_idx+1}: {display}\n"); sys.stdout.flush()
                eprint("Error: The setup command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.")
                sys.exit(1)
        # warmup
        for w in range(warmup_val):
            prep=prepare_per[b_idx]
            if prep is not None:
                p_cmd=prep
                for k,v in params.items(): p_cmd=p_cmd.replace("{"+k+"}", v)
                _,_,_,_,ec=execute_cmd(p_cmd, shell_exec, 0, {}, None, show_output)
                if ec!=0:
                    if not is_quiet:
                        sys.stdout.write(f"Benchmark {b_idx+1}: {display}\n"); sys.stdout.flush()
                    eprint("Error: The preparation command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.")
                    sys.exit(1)
            env_iter={"HYPERFINE_ITERATION": f"warmup-{w}"}
            _,_,_,_,ec=execute_cmd(cmd, shell_exec, overhead, env_iter, output_per[b_idx], show_output)
            if ec!=0 and not (ignore_all or ec in ignore_set):
                if not is_quiet:
                    sys.stdout.write(f"Benchmark {b_idx+1}: {display}\n"); sys.stdout.flush()
                eprint(f"Error: Command terminated with non-zero exit code {ec} in the first benchmark run. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.")
                sys.exit(1)
            concl=conclude_per[b_idx]
            if concl is not None:
                c_cmd=concl
                for k,v in params.items(): c_cmd=c_cmd.replace("{"+k+"}", v)
                execute_cmd(c_cmd, shell_exec, 0, {}, None, show_output)
        times=[]; users=[]; systems=[]; mems=[]; exit_codes=[]
        if runs_val is not None:
            target=runs_val
            for iter_idx in range(target):
                prep=prepare_per[b_idx]
                if prep is not None:
                    p_cmd=prep
                    for k,v in params.items(): p_cmd=p_cmd.replace("{"+k+"}", v)
                    _,_,_,_,ec=execute_cmd(p_cmd, shell_exec, 0, {}, None, show_output)
                    if ec!=0:
                        if not is_quiet:
                            sys.stdout.write(f"Benchmark {b_idx+1}: {display}\n"); sys.stdout.flush()
                        eprint("Error: The preparation command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.")
                        sys.exit(1)
                env_iter={"HYPERFINE_ITERATION": str(iter_idx)}
                wall,u,s,mem,ec=execute_cmd(cmd, shell_exec, overhead, env_iter, output_per[b_idx], show_output)
                if ec!=0 and not (ignore_all or ec in ignore_set):
