            elif where=="pipe":
                is_pipe=True; stdout_arg=subprocess.PIPE; stderr_arg=subprocess.PIPE
            elif where=="inherit":
                stdout_arg=None; stderr_arg=None
            else:
                try:
                    f=open(where,'wb')
