                        sys.exit(1)
                env_iter={"HYPERFINE_ITERATION": str(idx)}
                wall,u,s,mem,ec=execute_cmd(cmd, shell_exec, overhead, env_iter, output_per[b_idx], show_output)
                if ec!=0 and not (ignore_all or ec in ignore_set):
                    if not is_quiet:
                        sys.stdout.write(f"Benchmark {b_idx+1}: {display}\n"); sys.stdout.flush()
                    eprint(f"Error: Command terminated with non-zero exit code {ec} in the first benchmark run. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.")
                    sys.exit(1)
                times.append(wall); users.append(u); systems.append(s); mems.append(mem); exit_codes.append(ec)
                total_raw += wall + overhead
                idx+=1
                concl=conclude_per[b_idx]
                if concl is not None:
                    c_cmd=concl
                    for k,v in params.items(): c_cmd=c_cmd.replace("{"+k+"}", v)
                    execute_cmd(c_cmd, shell_exec, 0, {}, None, show_output)
        cl=cleanup_per[b_idx]
        if cl is not None:
            c_cmd=cl
            for k,v in params.items(): c_cmd=c_cmd.replace("{"+k+"}", v)
            execute_cmd(c_cmd, shell_exec, 0, {}, None, show_output)
        if not times:
            mean=0; stddev=None; median=0; um=0; sm=0; mi=0; ma=0
        else:
            mean=statistics.mean(times)
            if len(times)>=2:
                try: stddev=statistics.stdev(times)
                except: stddev=0.0
            else: stddev=None
            median=statistics.median(times)
            um=statistics.mean(users) if users else 0
            sm=statistics.mean(systems) if systems else 0
            mi=min(times); ma=max(times)
        results.append({
            "command": bench["command"],
            "display": display,
            "params": params,
            "mean": mean, "stddev": stddev, "median": median,
            "user": um, "system": sm, "min": mi, "max": ma,
            "times": list(times), "mems": mems, "exit_codes": exit_codes
        })

    if not is_quiet:
        for idx,res in enumerate(results):
            display=res["display"]
            unit=choose_console_unit(res["mean"], time_unit)
            if color_enabled:
                sys.stdout.write(f"\x1b[1mBenchmark \x1b[0m\x1b[1m{idx+1}\x1b[0m: {display}\n")
            else:
                sys.stdout.write(f"Benchmark {idx+1}: {display}\n")
            if len(res["times"])==1:
                mean_str=format_time(res["mean"], unit)
                user_str=format_time(res["user"], unit)
                system_str=format_time(res["system"], unit)
                t_padded=f"{mean_str:>16}"
                if color_enabled:
                    sys.stdout.write(f"  Time (\x1b[1;32mabs\x1b[0m ≡):        \x1b[1;32m{t_padded.strip()}\x1b[0m               [User: \x1b[34m{user_str}\x1b[0m, System: \x1b[34m{system_str}\x1b[0m]\n")
                else:
